let karimMenuStack=[];
const labelOf=x=>esc(x[state.lang]);
function karimMenuHTML(){let current=karimMenuStack.length?karimMenuStack[karimMenuStack.length-1]:null,items=current?current.children:NAV_TREE;
 return `<div class="progressive-menu-top"><strong>${current?labelOf(current):H('استكشف الموقع','Explore the site')}</strong><button type="button" data-menu-close aria-label="Close menu">✕</button></div>${current?`<button class="progressive-back" type="button" data-menu-back>${H('العودة','Back')} ↩</button>`:''}<div class="progressive-menu-rows">${items.map((x,i)=>`<div class="progressive-row">${x.children?`<button data-menu-next="${i}" type="button"><span>${current?labelOf(x):String(i+1).padStart(2,'0')+'. '+labelOf(x)}</span><span class="progressive-arrow">${H('‹','›')}</span></button>`:`<a href="${path(x.route||'')}">${current?labelOf(x):String(i+1).padStart(2,'0')+'. '+labelOf(x)} <span aria-hidden="true">↗</span></a>`}</div>`).join('')}</div>`;
}
function resetMenus(){karimMenuStack=[];const mobile=document.querySelector('#mobile-nav');if(mobile){mobile.classList.remove('open');mobile.innerHTML=karimMenuHTML()}const mt=document.querySelector('#mobile-toggle');if(mt){mt.setAttribute('aria-expanded','false');mt.textContent='☰'} }
function enhanceNav(){const mobile=$('#mobile-nav');if(!mobile)return;mobile.innerHTML=karimMenuHTML();mobile.classList.add('progressive-mobile-menu');
 const headerNode=$('.header-actions');if(headerNode&&!headerNode.querySelector('#sections-desktop')){const btn=document.createElement('button');btn.id='sections-desktop';btn.type='button';btn.className='sections-desktop';btn.textContent=H('الأقسام ☰','Sections ☰');headerNode.prepend(btn);btn.addEventListener('click',()=>{const opened=mobile.classList.toggle('open');if(opened){karimMenuStack=[];mobile.innerHTML=karimMenuHTML()}btn.setAttribute('aria-expanded',String(opened))})}
 mobile.onclick=e=>{const next=e.target.closest('[data-menu-next]');if(next){const ix=+next.dataset.menuNext;const items=karimMenuStack.length?karimMenuStack[karimMenuStack.length-1].children:NAV_TREE;karimMenuStack.push(items[ix]);mobile.innerHTML=karimMenuHTML();mobile.scrollTop=0;return}if(e.target.closest('[data-menu-back]')){karimMenuStack.pop();mobile.innerHTML=karimMenuHTML();mobile.scrollTop=0;return}if(e.target.closest('[data-menu-close]')){resetMenus();return}if(e.target.closest('a'))resetMenus()};
 $('#mobile-toggle')?.addEventListener('click',()=>{if(!mobile.classList.contains('open')){karimMenuStack=[];mobile.innerHTML=karimMenuHTML()}});
}
function sectionHead(eyebrow,title,description=''){return `<div class="container"><div class="ks-section-lead"><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div></div>`}
const verifiedDays={'legacy-5':[{day:1,ar:'من الرياض إلى باريس: بداية المغامرة',en:'From Riyadh to Paris: the first step',descAr:'في 5 مايو 2018 غادرت الرياض مع دراجتي متجهًا إلى باريس؛ بداية تجربة جديدة لم أكن أعرف تفاصيلها.',descEn:'On May 5, 2018 I left Riyadh with my bicycle for Paris, beginning a journey whose details were still unknown.'}]};
function dayCards(slug){const data=verifiedDays[slug]||[];return `<section class="ks-day-block"><div class="ks-section-lead"><span class="eyebrow">DAY BY DAY</span><h2>${H('أيام الرحلة','Journey day by day')}</h2><p>${H('تُضاف الأيام بحسب اليوميات والصور الموثقة فقط؛ لم نضع عدد أيام أو أحداثًا لم تُثبت.','Days are added only when firsthand notes or media establish them. Unverified days are not invented.')}</p></div>${data.length?`<div class="ks-day-grid">${data.map(x=>`<a class="ks-day-card" href="${path('day/'+slug+'/'+x.day)}"><span class="ks-day-num">${H('اليوم','Day')} ${x.day}</span><h3>${esc(H(x.ar,x.en))}</h3><p>${esc(H(x.descAr,x.descEn))}</p><strong>${H('شاهد تفاصيل هذا اليوم','Explore this day')} ↗</strong></a>`).join('')}</div>`:`<div class="ks-data-note">${H('عدد أيام المغامرة وتفاصيلها غير موثقين في المواد المتاحة حاليًا. احتفظنا برابط الرحلة الأصلي، وسنضيف كل يوم عندما تتوفر مادته.', 'The available archive does not establish the duration or daily account of this journey. Original references remain accessible until documented days can be added.')}</div>`}</section>`}
function dayPage(slug,day){const j=journeys.find(x=>x.slug===slug),d=(verifiedDays[slug]||[]).find(x=>x.day===Number(day));if(!j||!d)return notFound();return `<main>${pageHeader(esc(v(j,'title')),esc(H(d.ar,d.en)),'cycling.webp')}<section class="page-body"><div class="container ks-reading"><a class="plain-link" href="${path('journey/'+slug)}">${H('العودة إلى الرحلة','Back to journey')} ↩</a><span class="eyebrow">${H('اليوم','DAY')} ${day}</span><h2>${esc(H(d.ar,d.en))}</h2><p>${esc(H(d.descAr,d.descEn))}</p><p class="ks-data-note">${H('هذا اليوم مبني على الرواية المعتمدة؛ لا توجد تفاصيل يومية إضافية منشورة دون مصدر موثق.','This day is based on the approved account; no additional daily incidents are published without a verified source.')}</p><a class="plain-link" href="${path('journey/'+slug)}">${H('جميع أيام الرحلة','All journey days')} ↗</a></div></section></main>`}
function homepageExtra(){const cards=journeys.filter(x=>x.slug!=='legacy-14').slice(0,6);return `<section class="ks-home-extra"><div class="container"><div class="ks-section-lead"><span class="eyebrow">FEATURED ADVENTURES</span><h2>${H('اكتشف مغامراتي','Explore my adventures')}</h2><p>${H('اختر دولة لقراءة قصتها والاطلاع على الأيام الموثقة.','Choose a destination to explore its documented story and days.')}</p></div><div class="ks-card-grid">${cards.map(j=>`<a class="ks-journey-card" href="${path('journey/'+j.slug)}"><img loading="lazy" src="assets/${esc(j.img)}" alt="${H('صورة توضيحية','Illustrative image')}"><span class="ks-card-info"><strong>${esc(v(j,'title'))}</strong><small>${j.type==='cycling'?H('دراجة','Cycling'):H('مغامرة','Adventure')}</small><small>${H('درجة الصعوبة: لم تُقيّم بعد','Difficulty: not yet verified')}</small><em>${H('استكشف الرحلة','View journey')} ↗</em></span></a>`).join('')}</div></div></section><section class="ks-home-extra ks-follow"><div class="container"><div class="ks-section-lead"><span class="eyebrow">FOLLOW THE JOURNEY</span><h2>${H('من قلب المغامرة إلى منصاتك المفضلة','Follow the adventure on your favorite platforms')}</h2><p>${H('تابع الرحلات والقصص عبر حساباتي الرسمية.','Discover the journeys and stories on my official social accounts.')}</p></div><div class="ks-social-grid">${['instagram','tiktok','snapchat','facebook','x','youtube'].map((id,i)=>{let s=SOCIAL_PROFILES.find(x=>x.id===id),imgs=['hero-europe.webp','cycling.webp','journal-mountains.webp','hero-desert.webp','journal-greece.webp','hiking.webp'];return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" class="ks-social-tile" style="--tile-img:url('assets/${imgs[i]}')"><span>${socialIcon(s)} ${esc(s.name)}</span><small>${H('زيارة الحساب','Visit profile')} ↗</small></a>`}).join('')}</div><p class="ks-illustrative-note">${H('الصور الخلفية توضيحية وليست صور حساباتك الفعلية؛ سيتم استبدالها عند توفر صور مشاركاتك المعتمدة.','Background visuals are illustrative and will be replaced with verified personal photographs.')}</p></div></section>`}
const ABOUT_PAGES={
 happiness:{ar:'خلّ السعادة عادة',en:'Make Happiness a Habit',pa:['السعادة لا تعني أن تكون الأيام خالية من المصاعب؛ بل أن نبحث عن المعنى والامتنان وسط تفاصيل الحياة اليومية.','هذه مساحة للتأمل في العادات الصغيرة التي تمنح اليوم قيمة: المبادرة، والفضول، والتواصل مع الآخرين، وتجربة ما هو جديد.'],pe:['Happiness is not the absence of challenges, but the practice of finding meaning and gratitude in everyday life.','This space explores small habits that bring value to our days: initiative, curiosity, human connection, and the willingness to learn.']},
 'after-sixty':{ar:'الحياة بعد الستين',en:'Life After Sixty',pa:['ليست الأعمار أرقامًا تحدد نهاية الفضول أو الرغبة في التعلم. إنها مراحل تتغير فيها نظرتنا إلى الوقت وما نريد أن نتركه من أثر.','هنا أفتح باب الحديث عن المغامرة والمعرفة والعطاء بعد الستين، دون تحويل العمر إلى عائق أمام الأحلام.'],pe:['Age does not put an end to curiosity or learning. Each stage invites us to reconsider our time and the legacy we hope to leave.','A space for reflection on exploration, learning, and giving after sixty — without treating age as a limit to possibility.']},
 'why-adventures':{ar:'لماذا أعشق المغامرات؟',en:'Why I Love Adventure',pa:['لأن كل طريق جديد فرصة لاكتشاف المكان والناس، واختبار النفس بعيدًا عن المألوف.','أحاول توثيق التجربة بصدق: ما عشته، وما تعلمته، وما يمكن أن يفيد غيري. وهكذا تصبح الرحلة أكثر من مجرد صورة تذكارية.'],pe:['Every unfamiliar road is a chance to understand a place, meet people and discover new aspects of myself.','My aim is to document what happened and what I learned, so the journey becomes more than a souvenir photograph.']},
 business:{ar:'رحلتي في المال والأعمال',en:'My Journey in Business',pa:['تضم مسيرتي جانبًا مهنيًا في التطوير العقاري والمشاريع السياحية والضيافة، إلى جانب اهتمامي بالسفر والتجارب الإنسانية.','تقدم ملفات أعمال الصعب تاريخًا وخبرات ومشروعات مختلفة. وتُعرض المعلومات المهنية هنا استنادًا إلى المواد التي قدمتها، مع إبقاء الادعاءات التشغيلية والأرقام التي تحتاج وثائق مؤيدة قيد المراجعة.'],pe:['My professional work includes real-estate development, hospitality and tourism, alongside travel and human stories.','The Al Saab business archive describes decades of work and different projects. Operational and numerical claims will be verified against supporting documents before public promotion.']},
 volunteering:{ar:'العمل التطوعي والمبادرات الإنسانية',en:'Volunteer Work & Humanitarian Initiatives',pa:['أؤمن أن قيمة الرحلة لا تقاس فقط بالمكان الذي نصل إليه، بل بالأثر الإنساني الذي نتركه.','يضم الأرشيف مواد مرتبطة بمشروعات مجتمعية. وتبقى تفاصيل التنفيذ والجهات المستفيدة والمواعيد مرتبطة بالمصادر الأصلية؛ لا ننسب إنجازًا غير مثبت.'],pe:['For me, the value of a journey is also measured by the human impact we leave behind.','The archive includes community-related records. Project details, beneficiaries and completion dates require original supporting material before claims are made.']}
,
 mosques:{ar:'بناء المساجد',en:'Mosque Construction',pa:['مساحة مخصصة لتوثيق المبادرات المتعلقة ببناء المساجد ودعمها، ضمن العمل التطوعي والمبادرات الإنسانية.','ستُضاف تفاصيل المبادرات والمواقع والصور والجهات المستفيدة بعد مراجعة المواد الأصلية؛ لا تُذكر مشروعات منجزة أو تبرعات محددة دون توثيق.'],pe:['A dedicated space to document mosque-building and support initiatives as part of community and charitable work.','Projects, places, photographs and beneficiaries will be added when original supporting records are available; no unverified claims of completed construction or donations are made.']},
 'quran-circles':{ar:'حلقات القرآن الكريم',en:'Quran Learning Circles',pa:['صفحة مخصصة للمبادرات المرتبطة بحلقات تعليم القرآن الكريم ودعمها، ضمن قسم العمل التطوعي.','نحتفظ بهذا القسم لتوثيق الحلقات ومواقعها وطبيعة المشاركة عند توفر معلومات موثوقة، دون نشر أسماء مستفيدين أو تفاصيل شخصية بغير إذن.'],pe:['A dedicated page for Quran-learning circles and related educational support initiatives within the volunteering section.','Verified programs, locations and the nature of involvement may be documented here as evidence becomes available, without disclosing beneficiary identities or private details without permission.']}
};
function aboutNewPage(slug){const x=ABOUT_PAGES[slug];if(!x)return notFound();return `<main>${pageHeader(H(x.ar,x.en),H('محطات من حياتي وفكرتي عن العالم','Stories from my life and outlook'),'hero-desert.webp')}<section class="page-body"><div class="container ks-reading"><span class="eyebrow">KARIM SAAB / ABOUT</span><h2>${esc(H(x.ar,x.en))}</h2>${(state.lang==='ar'?x.pa:x.pe).map(p=>`<p>${esc(p)}</p>`).join('')}${slug==='business'?`<a class="btn btn-outline" href="${path('projects')}">${H('المشاريع والمراجع','Projects & sources')} ↗</a>`:''}${slug==='volunteering'?`<div class="ks-card-grid">${['community-wells','community-iftar-eg','community-iftar-srilanka','community-orphans'].map(id=>{let s=window.KARIM_LIBRARY[id];return `<a class="ks-simple-card" href="${path('content/'+id)}">${esc(H(s.ar,s.en))} ↗</a>`}).join('')}${[{ar:'بناء المساجد',en:'Mosque Construction',route:'about/mosques'},{ar:'حلقات القرآن الكريم',en:'Quran Learning Circles',route:'about/quran-circles'}].map(x=>`<a class="ks-simple-card" href="${path(x.route)}">${esc(H(x.ar,x.en))} ↗</a>`).join('')}</div>`:''}</div></section></main>`}
function aboutNewHome(){const links=NAV_TREE.find(x=>x.id==='about').children.slice(0,6);return `<main>${pageHeader(H('من أنا','About Me'),H('رحلة الإنسان خلف المغامرة والعمل','The person behind the adventures and professional work'),'hero-desert.webp')}<section class="page-body"><div class="container"><div class="ks-section-lead"><span class="eyebrow">MY STORY</span><h2>${H('أكثر من طريق… وحكاية واحدة','Many paths, one story')}</h2><p>${H('التجارب، والاختيارات، والمبادرات، والمشروعات التي شكلت رحلتي.','The experiences, choices, initiatives and projects that shape my journey.')}</p></div><div class="ks-card-grid">${links.map((l,i)=>`<a class="ks-simple-card" href="${path(l.route||'about/volunteering')}"><span class="eyebrow">0${i+1}</span><h3>${labelOf(l)}</h3><small>${H('اقرأ المزيد','Read more')} ↗</small></a>`).join('')}</div><div class="ks-references"><h3>${H('الأرشيف الأصلي','Original archive')}</h3>${OWNER_DROPDOWNS.about.filter(x=>x.route).map(x=>`<a href="${path(x.route)}">${esc(H(x.ar,x.en))} ↗</a>`).join('')}</div></div></section></main>`}
function roadStories(){return `<main>${pageHeader(H('حكايات من الطريق','Stories from the Road'),H('مواقف ودروس من الرحلات الموثقة','Moments and lessons from documented journeys'),'journal-mountains.webp')}<section class="page-body"><div class="container"><div class="ks-section-lead"><h2>${H('خلف كل رحلة حكاية','Every journey holds a story')}</h2><p>${H('هنا نتتبع ما رُوي من المواقف والتجارب كما حدث، بعيدًا عن التفاصيل المختلقة.','Documented experiences are presented as they happened, without invented incidents.')}</p></div><div class="ks-card-grid"><a class="ks-simple-card" href="${path('journey/legacy-5')}"><span class="eyebrow">FRANCE / DOCUMENTED</span><h3>${H('فرنسا — بداية المغامرة بالدراجة','France — the beginning of my cycling journey')}</h3><p>${H('رحلة باريس والهدف الذي رسمته نحو أمستردام، كما رويتها في قصتي المعتمدة.','From Paris, with Amsterdam as my intended destination, told in the approved account.')}</p></a><a class="ks-simple-card" href="${path('stories')}"><h3>${H('أفلام وقصص من الأرشيف','Films and archival stories')}</h3><p>${H('استكشف باقي المواد والعناوين الأصلية.','Browse other original materials and story titles.')}</p></a></div></div></section></main>`}
function guidesPage(){return `<main>${pageHeader(H('دليلك من تجربتي','Guides from My Experience'),H('نصائح السفر ومراجعات البلدان من منظور شخصي','Practical notes and personal country perspectives'),'hero-europe.webp')}<section class="page-body"><div class="container"><div class="ks-section-lead"><h2>${H('الدول من منظور المسافر',"Countries through a traveler's eyes")}</h2><p>${H('ستظهر الأماكن والتقييمات الشخصية حين تتوفر مشاهدات موثقة. أما قواعد الدخول والأسعار والمواعيد فتحتاج تحققًا حديثًا.','Places and personal ratings will be published only when first-hand evidence is available. Entry rules, prices and schedules require fresh verification.')}</p></div><div class="ks-card-grid">${journeys.filter(x=>x.slug!=='legacy-14').map(j=>`<a class="ks-simple-card" href="${path('guide/'+j.slug)}"><h3>${esc(v(j,'title'))}</h3><p>${H('المصدر ونصائح التوثيق والتقييم','Original source, travel notes & review')}</p><span>${H('افتح دليل الوجهة','Open destination guide')} ↗</span></a>`).join('')}</div></div></section></main>`}
function guideCountry(slug){const j=journeys.find(x=>x.slug===slug);if(!j)return notFound();return `<main>${pageHeader(esc(v(j,'title')),H('دليلك من تجربتي','Guides from my Experience'),'hero-europe.webp')}<section class="page-body"><div class="container ks-reading"><h2>${esc(v(j,'title'))}</h2><p>${esc(v(j,'desc'))}</p><div class="ks-facts"><article><strong>${H('أجمل الأماكن','Favorite places')}</strong><p>${H('لم يُعتمد ترتيب أو وصف شخصي للأماكن بعد.','No personal ranking or place description has been approved yet.')}</p></article><article><strong>${H('نصائح السفر','Travel tips')}</strong><p>${H('أتحقق من ظروف السفر والسكن والقوانين قبل كل رحلة؛ البيانات المتغيرة لا تُعرض هنا كحقائق حديثة دون مراجعة.','Check travel conditions, accommodation and regulations before departure. Changing information is not presented as current without verification.')}</p></article><article><strong>${H('تقييمي الشخصي','My personal rating')}</strong><p>${H('لم يُحدّد تقييم موثّق لهذه الوجهة بعد.','No verified personal rating for this destination has been provided.')}</p></article></div><a href="${path('journey/'+slug)}" class="btn btn-outline">${H('اذهب إلى المغامرة','Go to adventure')} ↗</a></div></section></main>`}
function shopHome(){return `<main>${pageHeader(H('تسوّق | من العالم إليك','Shop | From the World to You'),H('كل رحلة تترك حكاية… وبعض الحكايات تستحق أن تحملها معك.','Every journey leaves a story — some stories deserve to travel with you.'),'journal-desert.webp')}<section class="page-body"><div class="container"><div class="ks-section-lead"><span class="eyebrow">KARIM SAAB COLLECTION</span><h2>${H('تسوّق من عالم المغامرات','Shop the Spirit of Adventure')}</h2><p>${H('منتجات وهدايا مستوحاة من السفر والثقافات والتفاصيل التي تجعل لكل مكان ذاكرة خاصة. اكتشف المجموعة، وخذ معك شيئًا من روح المغامرة.','Collections and gifts inspired by travel, cultures and the small details that make each place unforgettable.')}</p></div><div class="ks-shop-groups">${[['men','رجال','Men','cycling.webp'],['women','نساء','Women','journal-greece.webp'],['kids','أطفال','Kids','hiking.webp']].map(([id,ar,en,img])=>`<a href="${path('shop/'+id)}" class="ks-shop-group"><img src="assets/${img}" loading="lazy" alt="${H('صورة توضيحية','Illustrative scene')}"><span>${H(ar,en)} ↗</span></a>`).join('')}</div><div class="ks-shop-gift-link"><a href="${path('shop/gifts')}">${H('هدايا من عالم المغامرات','Adventure Gifts & Bundles')} ↗</a></div><p class="ks-data-note">${H('المتجر قيد تجهيز بيانات المنتجات التجارية. الأسعار والمخزون والدفع والطلبات لن تُفعّل قبل اعتمادها.', 'Store checkout, prices, inventory and fulfilment require verification and an operational commerce provider.')}</p></div></section></main>`}
function shopGroup(group){const names={men:['للرجال','Men'],women:['للنساء','Women'],kids:['للأطفال','Kids'],gifts:['هدايا وباقات المغامرات','Adventure Gifts & Bundles']};if(!names[group])return notFound();const visible=group==='gifts'?SHOP_CATEGORIES.filter(x=>['product-bags','product-artworks','product-magnets','product-mugs','product-perfumes','product-soaps'].includes(x.id)):SHOP_CATEGORIES.filter(x=>x.group.includes(group));return `<main>${pageHeader(H(...names[group]),H('اكتشف الأصناف المقترحة ضمن تشكيلة KARIM SAAB','Explore planned KARIM SAAB product categories'),'hospitality.jpg')}<section class="page-body"><div class="container"><p class="ks-data-note">${H('الأصناف التالية مخطط لها؛ الصور تمثيلية وليست صورًا للبضاعة الحقيقية. سيظهر السعر والتوفر بعد التحقق.', 'These are planned categories, not live offers. Images are illustrative; prices and stock will appear only when verified.')}</p><div class="ks-card-grid">${visible.map(p=>`<a class="ks-journey-card" href="${path('shop/item/'+p.id)}"><img loading="lazy" src="${p.img}" alt="${H('صورة توضيحية','Illustrative image')}"><span class="ks-card-info"><strong>${esc(H(p.ar,p.en))}</strong><small>${H('السعر عند توفر المنتج','Price pending')}</small><em>${H('تفاصيل المنتج','Product details')} ↗</em></span></a>`).join('')}</div></div></section></main>`}
function shopItem(id){const p=SHOP_CATEGORIES.find(x=>x.id===id);if(!p)return notFound();const apparel=['product-tshirts','product-hoodies','product-vests'].includes(id),perfume=id==='product-perfumes';let opts=apparel?['S','M','L','XL','XXL']:perfume?[H('حجم العبوة يحدد عند اعتماد المنتج','Size pending')]:[];return `<main>${pageHeader(esc(H(p.ar,p.en)),H('صفحة المنتج من مجموعة KARIM SAAB','KARIM SAAB Collection product detail'),'journal-desert.webp')}<section class="page-body"><div class="container ks-product-layout"><figure><img src="${p.img}" alt="${H('صورة توضيحية غير نهائية','Illustrative image, not final merchandise')}"/><figcaption>${H('صورة توضيحية — ليست صورة المنتج النهائي','Illustrative photograph, not the final merchandise')}</figcaption></figure><div class="ks-product-controls"><span class="eyebrow">KARIM SAAB COLLECTION</span><h2>${esc(H(p.ar,p.en))}</h2><p>${H('تفاصيل العرض ستظهر هنا بعد إضافة صور المنتج الحقيقي ومواصفاته وأسعاره.', 'Real product photos, specifications and pricing will appear after approval.')}</p><div class="ks-product-price">${H('السعر: غير محدد','Price: not yet set')}</div><p class="ks-stock-state">${typeof window.KARIM_APPROVED_STOCK?.[id]?.quantity==='number'&&window.KARIM_APPROVED_STOCK[id].quantity===0?H('نفدت الكمية','Sold Out'):H('حالة المخزون: بانتظار التحقق','Stock status: awaiting confirmation')}</p>${opts.length?`<label for="ks-size">${apparel?H('المقاس المقترح (غير معتمد بعد)','Size concept (not yet approved)'):H('حجم العبوة','Volume')}</label><select id="ks-size" disabled><option>${H('بانتظار بيانات المنتج','Awaiting product details')}</option>${opts.map(x=>`<option>${x}</option>`).join('')}</select>`:''}<label for="ks-color">${H('اللون','Color')}</label><select id="ks-color" disabled><option>${H('الألوان تُحدّد عند اعتماد المخزون','Colors pending confirmation')}</option></select><label for="ks-quantity">${H('الكمية','Quantity')}</label><input id="ks-quantity" type="number" min="1" value="1" disabled/><button class="btn btn-gold" type="button" disabled>${H('الشراء غير مفعل بعد','Checkout not available yet')}</button><p class="ks-data-note">${H('لن نستقبل طلبات قبل ربط دفع حقيقي ومخزون وشحن موثوق.', 'Orders cannot be accepted until a secure checkout, inventory and shipping process is configured.')}</p><details open><summary>${H('الوصف','Description')}</summary><p>${H('هذا الصنف من مجموعة المنتجات المخطط لها، وتضاف معلومات الخامات والمقاس والتصنيع بعد اعتمادها.','This is a planned collection category. Materials, sizes and production details require approval.')}</p></details><details><summary>${H('دليل المقاسات والمعلومات الإضافية','Size guide & additional information')}</summary><p>${H('لا نعرض جدول قياسات أو خامات أو بلد تصنيع دون بيانات المنتج الفعلية.','No measurements, materials or country of manufacture are claimed without product data.')}</p></details><details><summary>${H('التقييمات','Reviews')}</summary><p>${H('التقييمات متاحة بعد وجود مشتريات ومراجعات حقيقية.','Reviews will appear only when submitted by verified customers.')}</p></details></div></div><div class="container"><div class="ks-section-lead"><h2>${H('قد يعجبك أيضًا','Related categories')}</h2></div><div class="ks-card-grid">${SHOP_CATEGORIES.filter(x=>x.id!==id).slice(0,3).map(x=>`<a class="ks-simple-card" href="${path('shop/item/'+x.id)}">${esc(H(x.ar,x.en))} ↗</a>`).join('')}</div></div></section></main>`}
function finalTags(){const ar=state.lang==='ar',r=state.route;let kind=r.startsWith('journey')||r.startsWith('day/')||r.startsWith('guide/')||r==='journeys'||r==='stories-road'||r==='travel-guides'?'journey':r==='projects'||r==='about/business'?'business':r.startsWith('shop')||r==='products'?'product':'';const tags=[...KARIM_SHARE_TAGS[state.lang],...(EXTRA_TAGS[kind]?.[state.lang]||[])];return `<div class="ks-end-links"><div><span class="eyebrow">${H('تابع وشارك','FOLLOW & SHARE')}</span><strong>${H('المزيد من رحلاتي وأعمالي','More journeys & stories')}</strong></div><div class="ks-hashtags">${[...new Set(tags)].map(t=>`<span>${esc(t)}</span>`).join(' ')}</div><a href="https://linktr.ee/ALSAABB" target="_blank" rel="noopener noreferrer">${H('جميع حساباتي الرسمية عبر Linktree','Official channels via Linktree')} ↗</a></div>`}
function shareHref(){const loc=location.href.split('#')[0].split('?')[0];const base=loc.endsWith('/')?loc:loc.slice(0,loc.lastIndexOf('/')+1);const route=(state.route||'home').split('?')[0];let slug=route.replace(/[^\w\/-]/g,'').split('/').filter(Boolean).join('-');return new URL('share/'+state.lang+'/'+(slug||'home')+'.html',base).href}
function shareUI(){return `<section class="ks-share-wrap"><div class="container"><h2>${H('أعجبتك هذه الصفحة؟ شاركها','Enjoyed this page? Share it')}</h2><div class="ks-share-buttons"><button type="button" data-ks-share="native">${H('المزيد من التطبيقات','More apps')}</button><button type="button" data-ks-share="whatsapp">WhatsApp</button><button type="button" data-ks-share="facebook">Facebook</button><button type="button" data-ks-share="x">X</button><button type="button" data-ks-share="telegram">Telegram</button><button type="button" data-ks-share="pinterest">Pinterest</button><button type="button" data-ks-share="linkedin">LinkedIn</button><button type="button" data-ks-share="reddit">Reddit</button><button type="button" data-ks-share="tumblr">Tumblr</button><button type="button" data-ks-share="copy">${H('نسخ الرابط','Copy link')}</button></div><p id="ks-share-status" role="status" aria-live="polite">${H('تطبيقات إنستغرام وسناب وتيك توك يمكن اختيارها عبر زر «المزيد» متى دعم الجهاز ذلك.','Instagram, Snapchat and TikTok are available through the native share menu when supported by the device.')}</p></div></section>`}
function bindShare(){document.querySelectorAll('[data-ks-share]').forEach(btn=>btn.addEventListener('click',async()=>{const mode=btn.dataset.ksShare,link=shareHref(),title=document.title,st=$('#ks-share-status');if(location.protocol==='file:'){st.textContent=H('تعمل المشاركة برابط عام بعد نشر الملفات على موقعك.','Sharing needs a published public URL.');if(mode!=='copy')return;}if(mode==='copy'){try{await navigator.clipboard.writeText(link);st.textContent=H('تم نسخ الرابط','Link copied')}catch{st.textContent=link}return;}if(mode==='native'){if(navigator.share){try{await navigator.share({url:link,title})}catch{}}else st.textContent=H('استخدم نسخ الرابط للمشاركة بالتطبيقات الأخرى.','Copy the link to share in other apps.');return}const q=encodeURIComponent(link),t=encodeURIComponent(title);const services={whatsapp:`https://api.whatsapp.com/send?text=${t}%20${q}`,facebook:`https://www.facebook.com/sharer/sharer.php?u=${q}`,x:`https://twitter.com/intent/tweet?url=${q}&text=${t}`,telegram:`https://t.me/share/url?url=${q}&text=${t}`,pinterest:`https://pinterest.com/pin/create/button/?url=${q}&description=${t}`,linkedin:`https://www.linkedin.com/sharing/share-offsite/?url=${q}`,reddit:`https://www.reddit.com/submit?url=${q}&title=${t}`,tumblr:`https://www.tumblr.com/widgets/share/tool?canonicalUrl=${q}&title=${t}`};if(services[mode])window.open(services[mode],'_blank','noopener,noreferrer');}));}
function enhancedPage(){const r=state.route;let html=null;
 if(r==='about')html=aboutNewHome();else if(r.startsWith('about/'))html=aboutNewPage(r.slice(6));
 else if(r==='stories-road')html=roadStories();else if(r==='travel-guides')html=guidesPage();else if(r.startsWith('guide/'))html=guideCountry(r.slice(6));
 else if(r.startsWith('day/')){let [,slug,day]=r.split('/');html=dayPage(slug,day)}
 else if(r==='products')html=karimProductsPage();else if(r.startsWith('shop/item/'))html=shopItem(r.slice('shop/item/'.length));else if(r.startsWith('shop/'))html=shopGroup(r.slice(5));
 if(html){const old=document.querySelector('#app > main');if(old)old.outerHTML=html;document.title=(document.querySelector('main h1')?.textContent||'KARIM SAAB')+' | KARIM SAAB'}
 if(r===''){const main=document.querySelector('#app > main');if(main){main.insertAdjacentHTML('beforeend',homepageExtra())}}
 if(r.startsWith('journey/')){const slug=r.slice(8).split('?')[0],body=document.querySelector('main .detail-layout');if(body){body.insertAdjacentHTML('afterend',dayCards(slug));let h=body.querySelector('.side-box');if(h)h.insertAdjacentHTML('beforeend',`<a class="plain-link" href="${path('guide/'+slug)}">${H('دليل هذه الدولة','Destination guide')} ↗</a>`)}}
 if(r==='books'){const div=document.querySelector('.source-list-heading');if(div)div.querySelector('p').textContent=H('المؤلفات وأغلفتها ونسخ PDF المتاحة للقراءة؛ لا تُنشر المسودات.','Books, covers and available PDF reading copies; unpublished drafts are not shared.');}
 let main=document.querySelector('#app > main');if(main){main.insertAdjacentHTML('beforeend',`<div class="container">${finalTags()}</div>`);if(!['privacy','review'].includes(r))main.insertAdjacentHTML('beforeend',shareUI())}
 // Give every browser route a meaningful document title and description.
 const heading=document.querySelector('#app > main h1');if(heading){document.title=heading.textContent.trim()+' | KARIM SAAB';const d=document.querySelector('meta[name=description]');const p=document.querySelector('#app > main p');if(d)d.content=(p?.textContent||heading.textContent).trim().slice(0,170);}
 // Standalone review embeds its source imagery/PDFs in data URLs; deployed ZIP uses normal files.
 if(window.EMBED_ASSETS){document.querySelectorAll('#app img[src^="assets/"]').forEach(img=>{const name=img.getAttribute('src').split('/').pop();if(window.EMBED_ASSETS[name])img.src=window.EMBED_ASSETS[name]});document.querySelectorAll('#app .ks-social-tile').forEach(el=>{const m=(el.getAttribute('style')||'').match(/assets\/([a-z0-9-]+\.webp)/);if(m&&window.EMBED_ASSETS[m[1]])el.style.setProperty('--tile-img','url("'+window.EMBED_ASSETS[m[1]]+'")')});}
 if(window.EMBED_PDFS){document.querySelectorAll('#app a[href^="assets/books/"]').forEach(a=>{const name=a.getAttribute('href').split('/').pop();if(window.EMBED_PDFS[name])a.href=window.EMBED_PDFS[name]})}
 // Restore internal legacy sources for people following their original address; no deletion or redirect.
 enhanceNav();bindShare();
}
const _oldRender=render;
window.removeEventListener('hashchange',_oldRender);
render=function(){_oldRender();enhancedPage()};
window.addEventListener('hashchange',render);
render();
